/**
 * 🦊 Fox IA — version fichier unique
 *
 * Tout est ici : serveur, moteur IA, rendu 3D, générateur de sites et interface.
 * Démarrage :  npm install  puis  npm start
 *
 * Ne pas modifier à la main : ce fichier est généré par build-single.js
 */
'use strict';

/* ============ mini système de modules ============ */
const __mods = {};
function __def(name, fn) { __mods[name] = { fn, exports: null, loaded: false }; }
function __req(name) {
  const m = __mods[name];
  if (!m) return require(name);
  if (!m.loaded) {
    m.loaded = true;
    const module = { exports: {} };
    m.fn(module, module.exports, __req);
    m.exports = module.exports;
  }
  return m.exports;
}

/* ============ interface embarquée ============ */
const __ASSETS = {
  "/index.html": { mime: "text/html; charset=utf-8", b64: "" },
  "/style.css": { mime: "text/css; charset=utf-8", b64: "" },
  "/app.js": { mime: "application/javascript; charset=utf-8", b64: "" },
  "/manifest.json": { mime: "application/manifest+json; charset=utf-8", b64: "" },
  "/icon.svg": { mime: "image/svg+xml; charset=utf-8", b64: "" },
};


