  p = p.replace(/^\s*(qui|que|de|d'|du|des|en|avec|sur|dans|pour|represente|representant|montrant)\b/gi, ' ');

  // élisions cassées : "dun" → "un", "lespace" → "l'espace"
  p = p.replace(/\bd'?(un|une|des)\b/gi, '$1');
  p = p.replace(/\bl'?(espace|eau|air|ocean|oc[ée]an)\b/gi, "l'$1");

