app.get('/api/chat/history', auth, wrap(async (req, res) => {
  // si un id précis est demandé mais n'existe plus, on renvoie un fil vide
  if (req.query.conv) {
    const existe = await q.get('SELECT id,titre FROM conversations WHERE id=? AND user_id=?', [req.query.conv, req.user.id]);
    if (!existe) return res.json({ messages: [], conv: null, titre: null });
  }
  const conv = await convCourante(req.user.id, req.query.conv);
  const msgs = await q.all('SELECT id,role,content,created_at FROM messages WHERE conv_id=? ORDER BY id ASC LIMIT 300', [conv.id]);
  const creas = await q.all('SELECT id,type,prompt,file,meta,created_at FROM creations WHERE user_id=? AND (conv_id=? OR conv_id IS NULL) ORDER BY id ASC', [req.user.id, conv.id]);
  const restantes = creas.map(c => ({ ...c, meta: JSON.parse(c.meta || '{}') }));
  for (const m of msgs) {
    if (m.role !== 'assistant') continue;
    let kind = null;
    if (/Voilà ton image/i.test(m.content)) kind = 'image';
    else if (/Ta vidéo est prête/i.test(m.content)) kind = 'video';
    else if (/Ton site est en ligne/i.test(m.content)) kind = 'website';
    if (!kind) continue;
    const i = restantes.findIndex(c => c.type === kind);
    if (i === -1) continue;
    const c = restantes.splice(i, 1)[0];
    m.kind = kind;
    m.meta = c.meta;
    m.prompt = c.prompt;
    m.id = c.id;
    if (kind === 'image') m.image = `/gen/${c.file}`;
    if (kind === 'video') m.frames = c.meta.frames || [`/gen/${c.file}`];
    if (kind === 'website') m.url = `/gen/${c.file}`;
  }
  res.json({ messages: msgs, conv: conv.id, titre: conv.titre });
}));
app.delete('/api/chat/history', auth, wrap(async (req, res) => {
  if (req.query.conv) await q.run('DELETE FROM messages WHERE conv_id=? AND user_id=?', [req.query.conv, req.user.id]);
  else await q.run('DELETE FROM messages WHERE user_id=?', [req.user.id]);
  res.json({ ok: true });
}));

/* ---------------- régénérer la dernière réponse ---------------- */
app.post('/api/chat/regenerate', auth, wrap(async (req, res) => {
  const conv = await convCourante(req.user.id, req.body?.conv);
  const dernier = await q.get("SELECT id,content FROM messages WHERE conv_id=? AND role='user' ORDER BY id DESC LIMIT 1", [conv.id]);
  if (!dernier) return res.status(400).json({ error: 'Aucun message à régénérer' });

  // on supprime l'ancienne réponse
  const rep = await q.get("SELECT id FROM messages WHERE conv_id=? AND role='assistant' ORDER BY id DESC LIMIT 1", [conv.id]);
  if (rep) await q.run('DELETE FROM messages WHERE id=?', [rep.id]);

  const msg = dernier.content;
  const hist = (await q.all('SELECT role,content FROM messages WHERE conv_id=? AND id<? ORDER BY id DESC LIMIT 12', [conv.id, dernier.id])).reverse();

  const intention = brain.detecter(msg);
  if (intention && req.user.lecture_seule) {
    const texte = `🔒 **Ton compte est en lecture seule.**\n\nTu peux discuter, mais la création d'images, vidéos et sites est désactivée.\n\nContacte l'administrateur via le bouton **Support** si tu penses qu'il s'agit d'une erreur.`;
    await enregistrer(texte);
    return res.json({ reply: texte, kind: 'bloque', conv: conv.id });
  }
  if (intention) {
    const feu = await quotas.verifier(req.user, intention.type === 'website' ? 'website' : intention.type);
    if (!feu.ok) return res.json({ reply: feu.message, kind: 'quota', conv: conv.id });
    if (intention.type === 'image') {
      const r = await faireImage(req.user, intention.prompt, intention.resolution, conv.id, req.body?.format);
      const d = r.meta.moteur === 'IA' ? `${r.meta.resolution} · style ${r.meta.style} · ${r.meta.poids}` : r.meta.resolution;
      const texte = `Nouvelle version ! 🎨\n\n**${intention.prompt}**\n\n*${d}*`;
      await q.run('INSERT INTO messages(user_id,conv_id,role,content) VALUES(?,?,?,?)', [req.user.id, conv.id, 'assistant', texte]);
      return res.json({ reply: texte, kind: 'image', image: r.url, meta: r.meta, prompt: intention.prompt, id: r.id, conv: conv.id });
    }
    if (intention.type === 'video') {
      const r = await faireVideo(req.user, intention.prompt, intention.duration, conv.id);
      const texte = `Nouvelle version ! 🎬\n\n**${intention.prompt}**\n\n*${r.meta.scenes} scènes · ${r.meta.duration} s*`;
      await q.run('INSERT INTO messages(user_id,conv_id,role,content) VALUES(?,?,?,?)', [req.user.id, conv.id, 'assistant', texte]);
      return res.json({ reply: texte, kind: 'video', frames: r.frames, meta: r.meta, prompt: intention.prompt, id: r.id, conv: conv.id });
    }
    const r = await faireSite(req.user, intention.prompt, conv.id);
    const texte = `Nouvelle version ! 🌐\n\n**${r.meta.name}** — ${r.meta.type}`;
    await q.run('INSERT INTO messages(user_id,conv_id,role,content) VALUES(?,?,?,?)', [req.user.id, conv.id, 'assistant', texte]);
    return res.json({ reply: texte, kind: 'website', url: r.url, html: r.html, meta: r.meta, prompt: intention.prompt, id: r.id, conv: conv.id });
  }

  const out = await ai.chat(hist, msg);
  const texte = (out.engine === 'connected' && out.text) ? out.text : brain.repondre(msg, hist);
  await q.run('INSERT INTO messages(user_id,conv_id,role,content) VALUES(?,?,?,?)', [req.user.id, conv.id, 'assistant', texte]);
  res.json({ reply: texte, kind: 'texte', conv: conv.id });
}));

