app.get('/api/admin/users', auth, admin, wrap(async (req, res) => {
  const cherche = (req.query.q || '').trim();
  const tri = ({ recent: 'id DESC', ancien: 'id ASC', actif: 'creations DESC', pseudo: 'pseudo ASC' })[req.query.tri] || 'id ASC';
  const base = `SELECT id,pseudo,email,role,provider,banned,credits,avatar,created_at,ip,
      ban_motif,ban_expire,avertissements,lecture_seule,derniere_visite,
      (SELECT COUNT(*) FROM creations c WHERE c.user_id=users.id) AS creations,
      (SELECT COUNT(*) FROM tickets t WHERE t.user_id=users.id) AS tickets
    FROM users`;
  const users = cherche
    ? await q.all(`${base} WHERE ${PG ? 'pseudo ILIKE ? OR email ILIKE ?' : 'LOWER(pseudo) LIKE LOWER(?) OR LOWER(email) LIKE LOWER(?)'} ORDER BY ${tri}`,
        [`%${cherche}%`, `%${cherche}%`])
    : await q.all(`${base} ORDER BY ${tri}`);
  res.json({ users });
}));

