app.patch('/api/admin/users/:id', auth, admin, wrap(async (req, res) => {
  const { role, credits } = req.body || {};
  const target = await q.get('SELECT * FROM users WHERE id=?', [req.params.id]);
  if (!target) return res.status(404).json({ error: 'Utilisateur introuvable' });
  if (Number(target.id) === 1 && role === 'user')
    return res.status(400).json({ error: 'Le fondateur ne peut pas être rétrogradé' });
  await q.run('UPDATE users SET role=COALESCE(?,role), credits=COALESCE(?,credits) WHERE id=?',
    [role || null, credits ?? null, req.params.id]);
  if (role) await mod.notifier(target.id, role === 'admin' ? '👑 Tu es administrateur' : 'Rôle modifié',
    role === 'admin' ? 'Tu as désormais accès à l\'espace administrateur.' : 'Ton rôle est passé à « membre ».',
    role === 'admin' ? 'success' : 'info');
  await log('user_update', `#${req.params.id} par ${req.user.pseudo}`);
  res.json({ ok: true });
}));

app.delete('/api/admin/users/:id', auth, admin, wrap(async (req, res) => {
  if (Number(req.params.id) === 1) return res.status(400).json({ error: 'Le compte fondateur est protégé' });
  const cible = await q.get('SELECT pseudo,role FROM users WHERE id=?', [req.params.id]);
  if (!cible) return res.status(404).json({ error: 'Utilisateur introuvable' });
  if (cible.role === 'admin' && req.user.id !== 1)
    return res.status(403).json({ error: 'Seul le fondateur peut supprimer un administrateur' });
  for (const tbl of ['creations', 'messages', 'conversations', 'notifs', 'sanctions', 'quotas'])
    { try { await q.run(`DELETE FROM ${tbl} WHERE user_id=?`, [req.params.id]); } catch {} }
  await q.run('DELETE FROM users WHERE id=?', [req.params.id]);
  await log('user_delete', `${cible.pseudo} supprimé par ${req.user.pseudo}`, 'warn');
  res.json({ ok: true });
}));

/* ─── sanctions ─── */
app.post('/api/admin/users/:id/sanction', auth, admin, wrap(async (req, res) => {
  const { action, duree, motif, bloquerIp } = req.body || {};
  const u = await q.get('SELECT * FROM users WHERE id=?', [req.params.id]);
  if (!u) return res.status(404).json({ error: 'Utilisateur introuvable' });
  if (Number(u.id) === 1) return res.status(400).json({ error: 'Le compte fondateur est protégé' });
  if (u.role === 'admin' && req.user.id !== 1)
    return res.status(403).json({ error: 'Seul le fondateur peut sanctionner un administrateur' });

  const texte = String(motif || '').trim();
  if (['ban', 'avertir', 'lecture_seule'].includes(action) && !texte)
    return res.status(400).json({ error: 'Un motif est obligatoire' });

  let out = {};
  switch (action) {
    case 'ban':
      out = await mod.bannir(u, { duree: duree || 'def', motif: texte, par: req.user.pseudo, bloquerIp: Boolean(bloquerIp) });
      break;
    case 'debannir':      await mod.debannir(u, req.user.pseudo); break;
    case 'avertir':       out = await mod.avertir(u, texte, req.user.pseudo); break;
    case 'lecture_seule': await mod.lectureSeule(u, true, texte, req.user.pseudo); break;
    case 'lever_lecture': await mod.lectureSeule(u, false, '', req.user.pseudo); break;
    case 'reset_avert':   await mod.reinitialiserAvertissements(u, req.user.pseudo); break;
    default: return res.status(400).json({ error: 'Action inconnue' });
  }
  res.json({ ok: true, ...out });
}));

