/* ─── graphiques d'activité ─── */
app.get('/api/admin/activite', auth, admin, wrap(async (req, res) => {
  const jours = Math.min(30, Math.max(7, Number(req.query.jours) || 14));
  const depuis = new Date(Date.now() - (jours - 1) * 86400000).toISOString().slice(0, 10);

  // on récupère les dates brutes puis on regroupe en JavaScript :
  // plus simple et identique sur SQLite comme sur PostgreSQL.
  const serie = async (table) => {
    const rows = await q.all(`SELECT created_at FROM ${table} WHERE created_at >= ?`, [depuis + ' 00:00:00']);
    const map = {};
    for (const r of rows) {
      const d = r.created_at instanceof Date
        ? r.created_at.toISOString().slice(0, 10)
        : String(r.created_at).slice(0, 10);
      map[d] = (map[d] || 0) + 1;
    }
    const out = [];
    for (let i = jours - 1; i >= 0; i--) {
      const j = new Date(Date.now() - i * 86400000).toISOString().slice(0, 10);
      out.push({ jour: j, n: map[j] || 0 });
    }
    return out;
  };

  res.json({
    jours,
    inscriptions: await serie('users'),
    creations: await serie('creations'),
    messages: await serie('messages'),
    tickets: await serie('tickets')
  });
}));

/* ─── export CSV ─── */
app.get('/api/admin/export/:quoi', auth, admin, wrap(async (req, res) => {
  const csv = (entetes, lignes) => {
    const ech = v => `"${String(v ?? '').replace(/"/g, '""').replace(/\n/g, ' ')}"`;
    return '\uFEFF' + [entetes.join(';'), ...lignes.map(l => l.map(ech).join(';'))].join('\n');
  };
  let nom, contenu;
  if (req.params.quoi === 'users') {
    const rows = await q.all(`SELECT id,pseudo,email,role,provider,banned,avertissements,lecture_seule,created_at,
      (SELECT COUNT(*) FROM creations c WHERE c.user_id=users.id) AS creations FROM users ORDER BY id`);
    nom = 'membres';
    contenu = csv(['ID', 'Pseudo', 'Email', 'Rôle', 'Source', 'Banni', 'Avertissements', 'Lecture seule', 'Inscrit le', 'Créations'],
      rows.map(u => [u.id, u.pseudo, u.email, u.role, u.provider, u.banned ? 'oui' : 'non',
        u.avertissements || 0, u.lecture_seule ? 'oui' : 'non', u.created_at, u.creations]));
  } else if (req.params.quoi === 'tickets') {
    const rows = await q.all('SELECT * FROM tickets ORDER BY id');
    nom = 'tickets';
    contenu = csv(['ID', 'Auteur', 'Email', 'Catégorie', 'Priorité', 'Statut', 'Sujet', 'Message', 'Réponse', 'Date'],
      rows.map(t => [t.id, t.pseudo, t.email, t.category, t.priority, t.status, t.subject, t.message, t.admin_reply || '', t.created_at]));
  } else if (req.params.quoi === 'creations') {
    const rows = await q.all('SELECT c.id,u.pseudo,c.type,c.prompt,c.created_at FROM creations c LEFT JOIN users u ON u.id=c.user_id ORDER BY c.id');
    nom = 'creations';
    contenu = csv(['ID', 'Auteur', 'Type', 'Description', 'Date'], rows.map(c => [c.id, c.pseudo, c.type, c.prompt, c.created_at]));
  } else return res.status(400).json({ error: 'Export inconnu' });

  res.setHeader('Content-Type', 'text/csv; charset=utf-8');
  res.setHeader('Content-Disposition', `attachment; filename="foxia-${nom}-${new Date().toISOString().slice(0, 10)}.csv"`);
  res.send(contenu);
}));

