app.post('/api/admin/tickets/bulk', auth, admin, wrap(async (req, res) => {
  const ids = (req.body?.ids || []).filter(n => Number.isInteger(Number(n))).map(Number);
  const action = req.body?.action;
  if (!ids.length) return res.status(400).json({ error: 'Aucun ticket sélectionné' });
  const marques = ids.map(() => '?').join(',');
  if (action === 'supprimer') await q.run(`DELETE FROM tickets WHERE id IN (${marques})`, ids);
  else if (['ouvert', 'encours', 'resolu'].includes(action))
    await q.run(`UPDATE tickets SET status=? WHERE id IN (${marques})`, [action, ...ids]);
  else return res.status(400).json({ error: 'Action inconnue' });
  await log('tickets_bulk', `${action} sur ${ids.length} ticket(s) par ${req.user.pseudo}`);
  res.json({ ok: true, traites: ids.length });
}));

