  const niveau = req.query.niveau, ev = (req.query.event || '').trim();
  let sql = 'SELECT * FROM logs', cond = [], args = [];
  if (niveau && niveau !== 'tous') { cond.push('level=?'); args.push(niveau); }
  if (ev) { cond.push(PG ? 'event ILIKE ?' : 'LOWER(event) LIKE LOWER(?)'); args.push(`%${ev}%`); }
